CREATE TABLE public.referral_invitee_rewards(receipt_id uuid PRIMARY KEY REFERENCES public.referral_cash_receipts(id), user_id uuid NOT NULL REFERENCES public.profiles(id), amount_paise bigint NOT NULL CHECK(amount_paise>0), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.referral_invitee_rewards TO authenticated;
GRANT ALL ON public.referral_invitee_rewards TO service_role;
ALTER TABLE public.referral_invitee_rewards ENABLE ROW LEVEL SECURITY;
CREATE POLICY invitee_reward_owner ON public.referral_invitee_rewards FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.assign_account_referral_code() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.referral_code:='G1'||upper(replace(NEW.id::text,'-','')); RETURN NEW; END $$;
CREATE TRIGGER auto_account_referral_code BEFORE INSERT ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.assign_account_referral_code();
CREATE OR REPLACE FUNCTION public.confirm_referral_cash(_user uuid,_reference text,_amount_paise bigint) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE receipt uuid; ref uuid; prize bigint; recipient uuid; BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'ADMIN_ONLY'; END IF; IF _amount_paise<=0 OR _amount_paise>100000000000 OR length(trim(_reference))<3 OR length(trim(_reference))>120 THEN RAISE EXCEPTION 'INVALID_RECEIPT'; END IF; INSERT INTO public.referral_vip_campaign(id) VALUES(true) ON CONFLICT DO NOTHING; INSERT INTO public.referral_cash_receipts(user_id,reference,amount_paise,confirmed_by) VALUES(_user,trim(_reference),_amount_paise,auth.uid()) RETURNING id INTO receipt; SELECT referrer_id INTO ref FROM public.referral_vip_joins WHERE joined_user=_user; IF ref IS NOT NULL THEN prize:=(_amount_paise*20)/100; IF prize>0 THEN INSERT INTO public.referral_cash_rewards(receipt_id,user_id,amount_paise) VALUES(receipt,ref,prize); INSERT INTO public.referral_invitee_rewards(receipt_id,user_id,amount_paise) VALUES(receipt,_user,prize); FOREACH recipient IN ARRAY ARRAY[ref,_user] LOOP IF public.can_notify(recipient) THEN INSERT INTO public.notifications(user_id,message) VALUES(recipient,'నిర్ధారించిన చెల్లింపుపై మీ 20% నగదు బహుమతి ₹'||(prize::numeric/100)||' నమోదైంది. పరిచయం చేసిన వ్యక్తి, చేరిన వ్యక్తి ఇద్దరికీ వేర్వేరుగా 20% లెక్క నమోదవుతుంది; ఇది బ్యాంకుకు పంపినట్లు కాదు.'); END IF; END LOOP; END IF; END IF; RETURN receipt; END $$;
COMMENT ON TABLE public.referral_cash_rewards IS 'Direct inviter receives 20 percent of confirmed referred payment; no ancestor commissions or payout claim.';
COMMENT ON TABLE public.referral_invitee_rewards IS 'Invited payer separately receives 20 percent of the same confirmed payment; owner-only balance, not a payout receipt.';
CREATE FUNCTION public.referral_vip_slots() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('total',100,'occupied',least(count(*),100),'remaining',greatest(100-count(*),0),'as_of',now()) FROM public.referral_vip_ranks() $$;
REVOKE ALL ON FUNCTION public.referral_vip_slots() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.referral_vip_slots() TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.my_referral_vip() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n bigint; r bigint; cutoff bigint; needed bigint; inviter_reward bigint; invitee_reward bigint; BEGIN IF auth.uid() IS NULL OR NOT public.account_allowed(auth.uid()) THEN RAISE EXCEPTION 'SIGN_IN_REQUIRED'; END IF; SELECT joins,rank_no INTO n,r FROM public.referral_vip_ranks() WHERE user_id=auth.uid(); SELECT coalesce(min(joins),0) INTO cutoff FROM public.referral_vip_ranks() WHERE rank_no<=100; needed:=CASE WHEN r<=100 THEN 0 WHEN (SELECT count(*) FROM public.referral_vip_ranks())<100 THEN 1 ELSE greatest(1,cutoff-coalesce(n,0)+1) END; SELECT coalesce(sum(amount_paise),0) INTO inviter_reward FROM public.referral_cash_rewards WHERE user_id=auth.uid(); SELECT coalesce(sum(amount_paise),0) INTO invitee_reward FROM public.referral_invitee_rewards WHERE user_id=auth.uid(); RETURN jsonb_build_object('count',coalesce(n,0),'rank',r,'needed',needed,'vip',coalesce(r<=100,false),'reward_paise',inviter_reward+invitee_reward,'inviter_reward_paise',inviter_reward,'invitee_reward_paise',invitee_reward,'code',public.ensure_my_referral_code(),'invited_by',(SELECT referrer_id FROM public.referral_vip_joins WHERE joined_user=auth.uid()),'slots',public.referral_vip_slots()); END $$;